SELECT sc.SEC_SNAME AS `公司名称`, idx.ENDDATE AS `截止日期`, ROUND(idx.F110101 / 10000, 1) AS `归母净利润(万)` FROM VIEW_STK_FIN_IDX idx JOIN GET_A_SEC_CODE sc ON idx.COMCODE = sc.COMCODE AND sc.ISVALID = 1 WHERE sc.SEC_SNAME LIKE '%美的集团%' AND idx.ISVALID = 1 AND idx.F110101 IS NOT NULL AND YEAR(idx.ENDDATE) = 2025 AND MONTH(idx.ENDDATE) = 12 AND DAY(idx.ENDDATE) = 31 ORDER BY idx.ENDDATE DESC LIMIT 1;
